function searchInlineDocument(raw,query){
 if(!query)return {items:[],total:0,returned:0,truncated:false};const needle=query.toLocaleLowerCase(),items=[],stack=[['',raw]];let total=0;
 while(stack.length){const [pointer,value]=stack.pop();if(value&&typeof value==='object'&&Object.keys(value).length){const entries=Object.entries(value);for(let i=entries.length-1;i>=0;i--){const [k,v]=entries[i];stack.push([pointer+'/'+k.replace(/~/g,'~0').replace(/\//g,'~1'),v]);}}else{const text=typeof value==='string'?value:JSON.stringify(value);if((text||'').toLocaleLowerCase().includes(needle)||pointer.toLocaleLowerCase().includes(needle)){total++;if(items.length<200)items.push({pointer,preview:(text||'').slice(0,260),value_length:(text||'').length});}}}
 return {items,total,returned:items.length,truncated:total>items.length};
}
